import { formatMoney } from '../../ui/money';
import { useDashboard } from './dashboard';

// The dashboard summary: counts of clients and projects, and how much money is still owed (the sum of
// UNPAID invoice amounts). Each value carries the data-testid the test reads; the outstanding total is
// rendered to two decimals to match a money amount.
export function Dashboard() {
  const { data, isPending, isError } = useDashboard();

  if (isPending) {
    return <p data-testid="dashboard-loading">Loading…</p>;
  }
  if (isError) {
    return <p data-testid="dashboard-error">Could not load the dashboard.</p>;
  }

  return (
    <dl data-testid="dashboard">
      <dt>Clients</dt>
      <dd data-testid="dashboard-clients-count">{data.clientsCount}</dd>
      <dt>Projects</dt>
      <dd data-testid="dashboard-projects-count">{data.projectsCount}</dd>
      <dt>Outstanding</dt>
      <dd data-testid="dashboard-outstanding-total">{formatMoney(data.outstandingTotal)}</dd>
    </dl>
  );
}

import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useContacts } from './contacts';

// At-a-glance counts for one client: how many projects and contacts they have. Both are derived
// from the SHARED query keys (CLAUDE.md rule 5) — ['projects'] and ['contacts'] — the same data the
// detail panels already show, filtered to this client. Nothing is copied into state and no parent
// hands these down; creating a project or contact anywhere invalidates the key and the counts
// refresh themselves.
type Project = { id: number; clientId: number };

export function ClientCounts({ clientId }: { clientId: number }) {
  const { data: projects } = useQuery({
    queryKey: ['projects'] as const,
    queryFn: () => getJson<Project[]>('/api/projects'),
  });
  const { data: contacts } = useContacts();

  const projectCount = (projects ?? []).filter((p) => p.clientId === clientId).length;
  const contactCount = (contacts ?? []).filter((c) => c.clientId === clientId).length;

  return (
    <dl data-testid="client-counts">
      <dt>Projects</dt>
      <dd data-testid="client-projects-count">{projectCount}</dd>
      <dt>Contacts</dt>
      <dd data-testid="client-contacts-count">{contactCount}</dd>
    </dl>
  );
}

import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useSearchParam, asFlag } from '../../url/useSearchParam';

// The projects a client is doing work on, shown in the client's detail. Server data is read straight
// from the SHARED ['projects'] query key (CLAUDE.md rule 5) — the same key the Projects page uses —
// so creating a project anywhere refreshes this list too, with no import of the projects feature.
// Each project carries its clientId, so the client context is just a filter on that shared data.
type Project = {
  id: number;
  name: string;
  clientId: number;
  clientName: string;
  archived: boolean;
  status: string;
};

export function ClientProjects({ clientId }: { clientId: number }) {
  // Only the client's ACTIVE work shows by default; a toggle (owning the `clientProjectsShowAll`
  // URL key, CLAUDE.md rule 4) reveals the finished and hidden (archived) ones too. The flag lives
  // in the URL so the revealed view outlives the click and is shareable.
  const [showAll, setShowAll] = useSearchParam('clientProjectsShowAll', asFlag);
  const { data: projects } = useQuery({
    queryKey: ['projects'] as const,
    queryFn: () => getJson<Project[]>('/api/projects'),
  });

  if (!projects) {
    return null;
  }

  // Active = being worked on (status ACTIVE) and not tucked away (archived). By default only those
  // show; "Show all" widens to every project the client owns, finished and archived included.
  const owned = projects.filter((project) => {
    if (project.clientId !== clientId) {
      return false;
    }
    return showAll || (project.status === 'ACTIVE' && !project.archived);
  });

  return (
    <>
      <button
        type="button"
        data-testid="client-projects-show-all"
        aria-pressed={showAll}
        onClick={() => setShowAll(showAll ? undefined : true)}
      >
        {showAll ? 'Show active only' : 'Show all projects'}
      </button>
      {owned.length === 0 ? (
        <p data-testid="client-projects-empty">No projects for this client yet.</p>
      ) : (
        // Reuse the project-row-<id>/project-name anchors inside the client-context table.
        <table data-testid="client-projects-table">
          <thead>
            <tr>
              <th>Name</th>
            </tr>
          </thead>
          <tbody>
            {owned.map((project) => (
              <tr key={project.id} data-testid={`project-row-${project.id}`}>
                <td data-testid="project-name">{project.name}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </>
  );
}

import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useSearchParam, asFlag } from '../../url/useSearchParam';

// The projects a client is doing work on, shown in the client's detail. Server data is read straight
